function syncArrivalDetailsButton(popup) {
  const button = popup?.querySelector('.gridatlas-card-bar .min');
  if (!button) return;
  const minimised = popup.classList.contains('gridatlas-min');
  button.textContent = minimised ? 'Details' : 'Map';
  button.title = minimised ? 'Show project details' : 'Minimise project details';
  button.setAttribute('aria-label', button.title);
  button.setAttribute('aria-expanded', String(!minimised));
  button.style.minHeight = '44px';
  button.style.minWidth = '62px';
}

function renderArrivalCardSummary(content, links, direction) {
  const popup = content?.closest?.('.maplibregl-popup');
  const label = content?.querySelector('.gridatlas-card-bar .label');
  if (!popup || !label) return;
  syncArrivalDetailsButton(popup);
  let summary = label.querySelector('.gridatlas-arrival-summary');
  if (!summary) {
    summary = document.createElement('span');
    summary.className = 'gridatlas-arrival-summary';
    summary.setAttribute('role', 'status');
    summary.setAttribute('aria-live', 'polite');
    summary.style.cssText = 'display:block;white-space:normal;font-size:11px;line-height:1.3;font-weight:normal';
    label.appendChild(summary);
  }
  label.style.whiteSpace = 'normal';
  label.style.minWidth = '0';
  const nearest = links[0] || links.beyondRadiusNearest;
  const kind = direction === 'from-substation' ? 'project' : 'substation';
  summary.textContent = nearest && Number.isFinite(nearest.km)
    ? 'Nearest mapped ' + kind + ': ' + (nearest.name || 'name not supplied')
      + ' | ' + nearest.km.toFixed(1) + ' km straight-line. Screening only; connection unverified.'
    : 'No mapped ' + kind + ' distance available. Connection unverified.';
}

